  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — maximize total profit (unit price minus raw material cost minus processing cost), or is there a different goal such as meeting a demand target or minimizing cost?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting alternatives within one coherent question."
}

{
  "action": "question",
